#!/usr/bin/env node
// Applies the fixes listed in PATCHES.md to a `types.d.ts` generated by
// PocketBase and writes the result to `jsvm.d.ts`.
//
//   node scripts/patch.mjs path/to/pb_data/types.d.ts
//
// Each patch must match at least once, so a patch that upstream has fixed (or
// changed the shape of) fails loudly instead of being skipped silently.

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const [, , input] = process.argv
if (!input) {
  console.error('Usage: node scripts/patch.mjs path/to/types.d.ts')
  process.exit(1)
}

let src = readFileSync(input, 'utf8')

const patches = [
  {
    name: 'store() is generic over the value type',
    find: /store\(\): \(store\.Store<string, any>\)/g,
    replace: 'store<T = any>(): (store.Store<string, T>)',
  },
  {
    name: 'expandRecords() optFetchFunc is optional',
    find: /(expandRecords\(records: Array<\(Record \| undefined\)>, expands: Array<string>, optFetchFunc)(: ExpandFetchFunc\))/g,
    replace: '$1?$2',
  },
  {
    name: 'MetaConfig has an appUrl alias for appURL',
    find: /^(\s+)appURL: string\n/gm,
    replace: '$1appURL: string\n$1appUrl: string\n',
  },
  {
    name: 'top-level namespaces are ambient (TS1046)',
    find: /^namespace /gm,
    replace: 'declare namespace ',
  },
  {
    name: 'rootFS overrides Root methods with different signatures (TS2430)',
    find: /interface rootFS extends Root\{\}/g,
    replace:
      "interface rootFS extends Omit<Root, 'open' | 'readDir' | 'readFile' | 'readLink' | 'stat' | 'lstat' | 'sub'>{}",
  },
  {
    name: 'fieldWithType.type is a string, not Field.type() (TS2430)',
    find: /interface fieldWithType extends (\w+) \{/g,
    replace: "interface fieldWithType extends Omit<$1, 'type'> {",
  },
]

for (const { name, find, replace } of patches) {
  const count = src.match(find)?.length ?? 0
  if (count === 0) {
    console.error(`Patch did not match: ${name}`)
    process.exit(1)
  }
  src = src.replace(find, replace)
  console.log(`${String(count).padStart(3)}x ${name}`)
}

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'jsvm.d.ts')
writeFileSync(out, src)
console.log(`Wrote ${out}`)
